  /* 桌面窗口正常关闭时先由主进程等待此函数确认下线，再释放服务；异常断网由心跳租期兜底。 */
  window.SanyStaffBeforeClose=async()=>{clearInterval(refreshTimer);clearInterval(heartbeatTimer);if(role()!=='service'||!state.token)return {offlineConfirmed:true,notApplicable:true};const owner=capture();const result=await api('/presence',{action:'offline'},{token:owner.token});if(current(owner)){state.presence=result.presence;updatePresence();}if(result.presence?.online)throw new Error('客服下线尚未确认。');return {offlineConfirmed:true};};
